    pub fn new(members: &'a Map<String, Value>) -> Self {
        Params { members }
    }

    /// Returns the value of `name`, or `None` if it is absent or `null`.
    pub fn get(&self, name: &str) -> Option<&'a Value> {
        self.members.get(name).filter(|value| !value.is_null())
    }

