#![allow(dead_code)]

use miniq::Broker;
use serde_json::Value;

/// Sends one command line to `broker` and returns the response object.
pub fn send(broker: &mut Broker, line: &str) -> Value {
    broker.handle_line(line.as_bytes())
}

