//! SendMessage (section 6), retention (section 4) and the delay that a send
//! starts with.

mod common;

use common::{fail, ok};
use miniq::Broker;
use serde_json::json;

fn standard(broker: &mut Broker, name: &str) {
    ok(broker, &format!(r#"{{"Command": "CreateQueue", "QueueName": "{name}"}}"#));
}

fn fifo(broker: &mut Broker, name: &str) {
    ok(broker, &format!(r#"{{"Command": "CreateQueue", "QueueName": "{name}", "Attributes": {{"Fifo": true}}}}"#));
}

fn counts(broker: &mut Broker, name: &str) -> serde_json::Value {
    ok(broker, &format!(r#"{{"Command": "GetQueueAttributes", "QueueName": "{name}"}}"#))["Counts"].clone()
}

#[test]
fn sends_get_increasing_message_ids_across_queues() {
    let mut broker = Broker::new();
