fn an_explicit_deduplication_id_overrides_the_body() {
    let mut broker = Broker::new();
    ok(&mut broker, r#"{"Command": "CreateQueue", "QueueName": "c.fifo", "Attributes": {"Fifo": true, "ContentBasedDeduplication": true}}"#);
    let first = ok(&mut broker, r#"{"Command": "SendMessage", "QueueName": "c.fifo", "Body": "one", "GroupId": "g", "DeduplicationId": "k"}"#);
    let second = ok(&mut broker, r#"{"Command": "SendMessage", "QueueName": "c.fifo", "Body": "two", "GroupId": "g", "DeduplicationId": "k"}"#);
    assert_eq!(second, first);
}

#[test]
fn deduplication_outlives_purge_but_not_the_queue() {
    let mut broker = Broker::new();
    fifo(&mut broker, "a.fifo");
    let first = ok(&mut broker, r#"{"Command": "SendMessage", "QueueName": "a.fifo", "Body": "x", "GroupId": "g", "DeduplicationId": "d"}"#);
    ok(&mut broker, r#"{"Command": "PurgeQueue", "QueueName": "a.fifo"}"#);
    let after_purge = ok(&mut broker, r#"{"Command": "SendMessage", "QueueName": "a.fifo", "Body": "x", "GroupId": "g", "DeduplicationId": "d"}"#);
    assert_eq!(after_purge, first);

    ok(&mut broker, r#"{"Command": "DeleteQueue", "QueueName": "a.fifo"}"#);
    fifo(&mut broker, "a.fifo");
    let fresh = ok(&mut broker, r#"{"Command": "SendMessage", "QueueName": "a.fifo", "Body": "x", "GroupId": "g", "DeduplicationId": "d"}"#);
