//! ReceiveMessage (section 6): delivery order, visibility, FIFO group rules
//! and dead-letter moves.

mod common;

use common::{fail, ok};
use miniq::Broker;
use serde_json::Value;

fn send(broker: &mut Broker, queue: &str, body: &str) {
    ok(broker, &format!(r#"{{"Command": "SendMessage", "QueueName": "{queue}", "Body": "{body}"}}"#));
}

fn send_fifo(broker: &mut Broker, queue: &str, body: &str, group: &str) {
    ok(
        broker,
        &format!(
            r#"{{"Command": "SendMessage", "QueueName": "{queue}", "Body": "{body}", "GroupId": "{group}", "DeduplicationId": "{body}"}}"#
        ),
    );
}

fn receive(broker: &mut Broker, extra: &str) -> Vec<Value> {
    let line = format!(r#"{{"Command": "ReceiveMessage", "QueueName": "{}"{extra}}}"#, queue_of(extra));
    ok(broker, &line)["Messages"].as_array().unwrap().clone()
}

// The queue name is passed through `extra` as `"QueueName": ...` is always first in our calls.
fn queue_of(extra: &str) -> &str {
    extra.split('"').nth(1).unwrap_or("")
}

fn bodies(messages: &[Value]) -> Vec<&str> {
    messages.iter().map(|m| m["Body"].as_str().unwrap()).collect()
}

fn counts(broker: &mut Broker, queue: &str) -> Value {
    ok(broker, &format!(r#"{{"Command": "GetQueueAttributes", "QueueName": "{queue}"}}"#))["Counts"].clone()
}

#[test]
