    for body in ["x", "y", "z"] {
        send(&mut broker, "a", body);
    }
    let first = ok(&mut broker, r#"{"Command": "ReceiveMessage", "QueueName": "a"}"#);
    assert_eq!(bodies(first["Messages"].as_array().unwrap()), ["x"]);
    let rest = ok(&mut broker, r#"{"Command": "ReceiveMessage", "QueueName": "a", "MaxMessages": 10}"#);
    assert_eq!(bodies(rest["Messages"].as_array().unwrap()), ["y", "z"]);
}

